{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "GSK2838232, a pentacyclic triterpenoid-derived drug with a carboxylic acid and basic amine side chain, showed poor oral bioavailability in initial human clinical studies; this is the closest structural analogue and supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Oleanolic acid, a pentacyclic triterpenoid acid, showed poor oral bioavailability in healthy volunteers after oral dosing, with low AUC and Cmax; the shared triterpenoid acid scaffold supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Glycyrrhizin, a triterpenoid acid, had an absolute oral bioavailability of approximately 0.25% in humans, demonstrating that large triterpenoid acids can be very poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Soticlestat had an absolute oral bioavailability of 12.6% in healthy volunteers, below the 20% threshold, supporting low F for a lipophilic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "SRT2104 had an absolute oral bioavailability of 13.8% in healthy volunteers, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Rilzabrutinib had an absolute oral bioavailability of 4.7-6.4% in humans, supporting low F for a complex oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DJ-927, a complex taxane, showed high oral bioavailability in a phase I trial, providing a counterexample that complex natural-product-like molecules can be orally bioavailable; however, its taxane scaffold and lack of the triterpenoid acid motif limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large pentacyclic triterpenoid acid with multiple fused rings, a carboxylic acid, and polar side chains. The most transferable experimental evidence—triterpenoid acids and complex lipophilic oral drugs—consistently shows low oral bioavailability (poor to ~14%), while the high-F examples are structurally distant. Therefore F < 20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability or human PK data for the query.",
    "All retrieved analogues have Morgan similarity below 0.22, limiting quantitative transfer.",
    "No solubility, permeability, or efflux-transporter data for the query.",
    "No formulation-specific oral bioavailability data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

